{
  "goal": "Deliver the one-room MVP that securely turns a RoomPlan bedroom scan into a canonical, versioned, constraint-aware scene with phone-to-web handoff, a three-pane web editor, typed conversational edits, deterministic validation, quick render, photoreal output tied to immutable scene state, single-step undo, and optional non-blocking splat preview.",
  "steps": [
    {
      "id": "step-1",
      "title": "Finalize the authoritative scene schema and semantic model",
      "description": "Lock the canonical scene schema, entity semantics, geometric frames, planner-facing references, and reason-code vocabulary in the shared contracts so every later surface builds on one authoritative model.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-2",
      "title": "Define scene snapshots, versioning boundaries, and undo semantics",
      "description": "Define immutable SceneSnapshot records, the mutable SceneHead pointer, non-authoritative sidecars, monotonic scene_version rules, and single-step undo semantics before any runtime mutations are added.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-3",
      "title": "Define the secure handoff and server-authoritative API contract",
      "description": "Fix the capture, handoff, scene read, plan, apply, undo, photoreal, job, and delete contracts so the server remains authoritative and scene access always flows through short-lived, scene-scoped credentials.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-4",
      "title": "Bootstrap the implementation workspace, shared contracts, and fixture scenes",
      "description": "Stand up the monorepo workspaces, initial migration, shared TypeScript and Swift contract surfaces, and fixture-first golden scenes so later implementation work can land against stable repo-native artifacts.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-5",
      "title": "Implement RoomPlan capture, ingest, and initial scene creation with deterministic parity",
      "description": "Turn the existing contract and ingest bootstrap into the first end-to-end vertical slice: persist POST /captures/roomplan results, store the initial SceneHead/SceneSnapshot/derived_state_cache plus handoff and video-upload artifacts, and wire the iOS companion upload path to the same shared payload shapes. Keep stable-ID assignment, scene mapping, and initial cache derivation in one pure module reused by fixtures, HTTP handlers, and replay tests, and make this the first hard verification seam by proving fixture replays create the same canonical scene output every time except for timestamps and opaque tokens.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-6",
      "title": "Stand up authenticated scene reads and the initial three-pane web editor shell",
      "description": "Implement POST /handoffs/redeem and authenticated GET /scenes/{scene_id}, then build the minimal web shell that redeems a handoff, loads the canonical read model, and renders scan, layout, and render panes plus selection state from server data only. Keep the scan pane read-only, support fixture-backed local loading during development, and avoid any client-side scene reconstruction so independent verification sees the same scene state the server stores.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-7",
      "title": "Add asset retrieval, proxy fallback, and deterministic quick rendering",
      "description": "Implement the curated asset manifest, server-side asset resolution, proxy fallback, and the fast render adapter that turns the committed snapshot plus editing_asset_refs into a renderable scene without mutating scene state. Share one scene-to-render mapping between backend and web, log fallback misses, and verify that layout and quick render stay version-synchronized even when exact assets are unavailable.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-8",
      "title": "Implement the deterministic mutation pipeline: preview/apply, validation, locking, and undo",
      "description": "Before adding any LLM behavior, build the pure mutation engine and wrap it with the server-authoritative preview/apply flow: preview persistence, single-use apply tokens, idempotency records, expected-version checks, lock enforcement, deterministic simulation, hard/soft constraint evaluation, atomic snapshot commits, derived-state recomputation, and one-step undo that creates a new head snapshot. Drive this step first with scripted typed operations and invalid-case fixtures so every reason code, conflict path, and undo rule is independently verifiable without conversational ambiguity.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-9",
      "title": "Build the constrained planner and chat-driven typed edit workflow",
      "description": "Layer conversational editing on top of the proven mutation engine by keeping the planner behind the existing PlannerResponse contract and by starting with a deterministic router/template fallback for common prompts and dedicated commands before enabling the full LLM path. Add selection-grounded chat UX, preview/accept/reject flows, clarification handling, and reason-code messaging, and keep golden prompt transcripts so planner behavior can be checked against the same typed operations that the validator already understands.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-10",
      "title": "Ship immutable-version photoreal generation, bookmarks, and gallery storage",
      "description": "Implement bookmark sidecars, POST /scenes/{scene_id}/photoreal, job tracking, and gallery reads so photoreal outputs are always keyed to scene_id, scene_version, scene_snapshot_id, and resolved camera parameters. Reuse quick-render conditioning inputs, keep retries idempotent and non-mutating, and verify that generating or revisiting older versions never rewrites the current editable scene head.",
      "requiredChecks": [
        "noop"
      ],
      "highStakes": true
    },
    {
      "id": "step-11",
      "title": "Add asynchronous splat jobs and scan-pane swap behavior",
      "description": "Finish the optional video path as a sidecar-only workflow: accept scene-scoped one-time video upload tokens, create or update splat jobs, expose job polling, and swap the scan pane from the RoomPlan preview to the splat asset when the job reaches ready. Preserve the current scene snapshot as the only editable source of truth, never increment scene_version for splat state changes, and keep the editor fully usable when the upload never happens or the job fails.",
      "requiredChecks": [
        "noop"
      ]
    },
    {
      "id": "step-12",
      "title": "Add observability, golden evaluation harnesses, and demo hardening",
      "description": "Close the verification gap that caused the escalation by adding structured logs, latency/error metrics, golden fixtures and transcripts for ingest, mutation, planner, photoreal, and splat flows, plus one reproducible end-to-end MVP script from capture through refresh. Because automated checks are still effectively noop, make the repo itself carry the acceptance evidence: replayable bedroom scans, scripted command sequences, version-linked gallery artifacts, and a demo runbook with clear fallback behavior for planner, photoreal, and splat failures.",
      "requiredChecks": [
        "noop"
      ]
    }
  ]
}

{
  "name": "roomview-mvp-workspace",
  "private": true,
  "version": "0.1.0",
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "verify:fixtures": "node ./scripts/verify-fixtures.mjs",
    "check": "npm run verify:fixtures"
  }
}

export * from "./primitives";
export * from "./scene";
export * from "./api";

import type {
  AssetId,
  BookmarkId,
  EntityId,
  ISO8601Timestamp,
  JobId,
  OBB3D,
  Point2D,
  Polygon2D,
  Pose3D,
  Provenance,
  RectOnSurface,
  RoomCoordinateFrame,
  SceneId,
  SnapshotId,
  SurfaceFrame,
  Units,
} from "./primitives";
import type { MaterialState } from "./primitives";

export const MUTATION_KIND_VALUES = ["initial_ingest", "edit_plan", "undo_restore"] as const;
export type MutationKind = (typeof MUTATION_KIND_VALUES)[number];

export const ROOM_TYPE_VALUES = ["bedroom"] as const;
export type RoomType = (typeof ROOM_TYPE_VALUES)[number];

export const SURFACE_TYPE_VALUES = ["wall", "floor", "ceiling"] as const;
export type SurfaceType = (typeof SURFACE_TYPE_VALUES)[number];

export const OPENING_TYPE_VALUES = ["door", "window", "closet_door"] as const;
export type OpeningType = (typeof OPENING_TYPE_VALUES)[number];

export const OBJECT_MOBILITY_VALUES = ["movable", "anchored", "fixed"] as const;
export type ObjectMobility = (typeof OBJECT_MOBILITY_VALUES)[number];

export const CHILD_MOVEMENT_POLICY_VALUES = ["move_with_parent", "independent"] as const;
export type ChildMovementPolicy = (typeof CHILD_MOVEMENT_POLICY_VALUES)[number];

export const HOST_RELATION_TYPE_VALUES = [
  "flush_to_wall",
  "mounted_to_wall",
  "embedded_in_wall",
  "ceiling_mounted",
] as const;
export type HostRelationType = (typeof HOST_RELATION_TYPE_VALUES)[number];

export const SUPPORT_KIND_VALUES = ["floor", "wall", "ceiling", "object"] as const;
export type SupportKind = (typeof SUPPORT_KIND_VALUES)[number];

export const FOCAL_ELEMENT_TYPE_VALUES = ["object", "opening", "fixed_element", "surface"] as const;
export type FocalElementType = (typeof FOCAL_ELEMENT_TYPE_VALUES)[number];

export const FOCAL_ELEMENT_ROLE_VALUES = ["primary", "secondary"] as const;
export type FocalElementRole = (typeof FOCAL_ELEMENT_ROLE_VALUES)[number];

export const CONSTRAINT_KIND_VALUES = [
  "opening_preserved",
  "walkway_clearance",
  "no_overlap_in_bounds",
  "anchor_integrity",
  "class_specific_clearance",
  "desk_near_window",
  "sofa_faces_focal_element",
  "primary_path_not_serpentine",
] as const;
export type ConstraintKind = (typeof CONSTRAINT_KIND_VALUES)[number];

export const CONSTRAINT_SEVERITY_VALUES = ["hard", "soft"] as const;
export type ConstraintSeverity = (typeof CONSTRAINT_SEVERITY_VALUES)[number];

export const ASSET_KIND_VALUES = ["gltf", "proxy_gltf"] as const;
export type AssetKind = (typeof ASSET_KIND_VALUES)[number];

export const SPLAT_STATUS_VALUES = ["queued", "processing", "ready", "failed"] as const;
export type SplatStatus = (typeof SPLAT_STATUS_VALUES)[number];

export const EDITABLE_OBJECT_CLASS_VALUES = [
  "bed",
  "nightstand",
  "desk",
  "chair",
  "table",
  "dresser",
  "bookshelf",
  "sofa",
  "rug",
  "lamp",
  "television",
  "storage",
] as const;
export type EditableObjectClass = (typeof EDITABLE_OBJECT_CLASS_VALUES)[number];

export type ObjectClass = EditableObjectClass | "generic_obstacle";

export interface SceneHead {
  scene_id: SceneId;
  source: "scanned";
  units: Units;
  current_snapshot_id: SnapshotId;
  current_scene_version: number;
  undo_base_snapshot_id: SnapshotId | null;
  updated_at: ISO8601Timestamp;
}

export interface SceneSnapshot {
  snapshot_id: SnapshotId;
  scene_id: SceneId;
  scene_version: number;
  based_on_snapshot_id: SnapshotId | null;
  mutation_kind: MutationKind;
  state: SceneState;
  editing_asset_refs: AssetRef[];
  created_at: ISO8601Timestamp;
}

export interface Scene {
  head: SceneHead;
  snapshot: SceneSnapshot;
  derived_state_cache: DerivedState | null;
  bookmarks: CameraBookmark[];
  photoreal_gallery: PhotorealEntry[];
  splat: SplatAssetRecord | null;
}

export interface SceneState {
  style_tags: string[];
  room: Room;
}

export interface Room {
  room_id: EntityId;
  room_type: RoomType;
  coordinate_frame: RoomCoordinateFrame;
  shell: Shell;
  objects: SceneObject[];
  constraints: ConstraintSpec[];
  focal_elements: FocalElementRef[];
  section_hints: string[];
}

export interface Shell {
  floor_polygon: Polygon2D;
  ceiling_height: number;
  surfaces: Surface[];
  named_wall_refs: NamedWallRef[];
  openings: Opening[];
  fixed_elements: FixedElement[];
}

export interface Surface {
  surface_id: EntityId;
  type: SurfaceType;
  geometry_ref: string;
  boundary: Polygon2D;
  surface_frame: SurfaceFrame | null;
  named_wall_ref_id: EntityId | null;
  material_state: MaterialState;
  user_locked: boolean;
  provenance: Provenance;
}

export interface Opening {
  opening_id: EntityId;
  host_surface_id: EntityId;
  type: OpeningType;
  rect: RectOnSurface;
  swing_zone: Polygon2D | null;
  keepout_zone: Polygon2D | null;
  connects_to_room_id: EntityId | null;
  provenance: Provenance;
}

export interface SceneObject {
  object_id: EntityId;
  class: ObjectClass;
  attributes: string[];
  parent_id: EntityId | null;
  child_movement_policy: ChildMovementPolicy;
  pose: Pose3D;
  obb: OBB3D;
  mobility: ObjectMobility;
  host: HostRelation | null;
  support: SupportRelation;
  asset_ref: AssetId | null;
  style_tags: string[];
  material_state: MaterialState | null;
  user_locked: boolean;
  provenance: Provenance;
}

export interface FixedElement {
  fixed_element_id: EntityId;
  class: string;
  pose: Pose3D;
  obb: OBB3D;
  host: HostRelation | null;
  support: SupportRelation;
  keepout_zone: Polygon2D | null;
  provenance: Provenance;
}

export interface AssetRef {
  asset_id: AssetId;
  kind: AssetKind;
  uri: string;
  bound_to: EntityId;
}

export interface SplatAssetRecord {
  scene_id: SceneId;
  source_scene_version: number;
  status: SplatStatus;
  asset_id: AssetId | null;
  uri: string | null;
  job_id?: JobId | null;
  updated_at: ISO8601Timestamp;
}

export interface NamedWallRef {
  wall_ref_id: EntityId;
  name: string;
  surface_ids: EntityId[];
  azimuth_degrees: number;
  inward_normal_xy: Point2D;
}

export interface HostRelation {
  relation_type: HostRelationType;
  host_surface_id: EntityId;
  anchor_rect: RectOnSurface | null;
}

export interface SupportRelation {
  support_kind: SupportKind;
  support_entity_id: EntityId;
  contact_patch: Polygon2D | RectOnSurface | null;
}

export interface FocalElementRef {
  entity_id: EntityId;
  entity_type: FocalElementType;
  role: FocalElementRole;
  reason: string;
}

export interface ConstraintSpec {
  constraint_id: EntityId;
  kind: ConstraintKind;
  severity: ConstraintSeverity;
  target_entity_ids: EntityId[];
  params: Record<string, unknown>;
  reason_code_on_fail: string | null;
}

export interface CameraBookmark {
  bookmark_id: BookmarkId;
  name: string;
  camera_pose: Pose3D;
  fov: number;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
}

export interface PhotorealEntry {
  entry_id: EntityId;
  asset_id: AssetId;
  scene_version: number;
  scene_snapshot_id: SnapshotId;
  bookmark_id: BookmarkId | null;
  camera_pose: Pose3D;
  fov: number;
  prompt_modifiers: string[];
  provider_metadata?: Record<string, unknown>;
  created_at: ISO8601Timestamp;
}

export interface DerivedState {
  zones: Array<Record<string, unknown>>;
  clearance_paths: Array<Record<string, unknown>>;
  soft_scores: Record<string, number>;
  hard_violations: Array<Record<string, unknown>>;
  selection_context_summary: string;
}

export interface OperationSummary {
  request_id: string;
  ops: Array<Record<string, unknown>>;
  timestamp: ISO8601Timestamp;
  user_message: string;
}

export type Object = SceneObject;

import type {
  AssetId,
  EntityId,
  ISO8601Timestamp,
  JobId,
  OBB3D,
  Point3D,
  Polygon2D,
  Pose3D,
  RectOnSurface,
  SceneId,
  SnapshotId,
  Vector3D,
} from "./primitives";
import type { MaterialState } from "./primitives";
import type { CameraBookmark, EditableObjectClass, Scene } from "./scene";

export const COMMAND_KIND_VALUES = ["generate_photoreal", "undo_last_change"] as const;
export type CommandKind = (typeof COMMAND_KIND_VALUES)[number];

export const JOB_KIND_VALUES = ["photoreal", "splat"] as const;
export type JobKind = (typeof JOB_KIND_VALUES)[number];

export const JOB_STATUS_VALUES = ["queued", "processing", "ready", "failed"] as const;
export type JobStatus = (typeof JOB_STATUS_VALUES)[number];

export const HANDOFF_GRANT_STATUS_VALUES = ["issued", "redeemed", "expired", "revoked"] as const;
export type HandoffGrantStatus = (typeof HANDOFF_GRANT_STATUS_VALUES)[number];

export const VIDEO_UPLOAD_TOKEN_STATUS_VALUES = ["issued", "used", "expired", "revoked"] as const;
export type VideoUploadTokenStatus = (typeof VIDEO_UPLOAD_TOKEN_STATUS_VALUES)[number];

export const REASON_CODE_VALUES = [
  "AUTH_REQUIRED",
  "SCENE_ACCESS_DENIED",
  "HANDOFF_EXPIRED",
  "HANDOFF_ALREADY_USED",
  "AMBIGUOUS_TARGET",
  "TARGET_NOT_FOUND",
  "VERSION_CONFLICT",
  "APPLY_TOKEN_INVALID",
  "APPLY_TOKEN_EXPIRED",
  "IDEMPOTENCY_CONFLICT",
  "ENTITY_LOCKED",
  "OBJECT_OVERLAP",
  "OUT_OF_BOUNDS",
  "OPENING_BLOCKED",
  "CLEARANCE_VIOLATION",
  "ANCHOR_VIOLATION",
  "UNSUPPORTED_CLASS",
  "ASSET_NOT_AVAILABLE",
  "PARENT_MOVE_VIOLATION",
  "UNDO_NOT_AVAILABLE",
  "SCENE_DELETED",
  "PHOTOREAL_PROVIDER_ERROR",
  "INVALID_CAPTURE",
  "ROOM_TYPE_NOT_SUPPORTED",
  "MULTI_ROOM_NOT_SUPPORTED",
  "VIDEO_UPLOAD_TOKEN_INVALID",
  "VIDEO_UPLOAD_TOKEN_EXPIRED",
  "VIDEO_UPLOAD_TOKEN_ALREADY_USED",
] as const;
export type ReasonCode = (typeof REASON_CODE_VALUES)[number];

export interface RoomPlanCaptureRequest {
  request_id: string;
  client_capture_id: string;
  roomplan_payload: RoomPlanPayload;
  capture_metadata: CaptureMetadata;
  supplementary_detections: SupplementaryDetection[] | null;
}

export interface RoomPlanPayload {
  schema_version: string;
  room_type: "bedroom" | string;
  coordinate_frame: {
    origin: Point3D;
    x_axis: Vector3D;
    y_axis: Vector3D;
    z_axis: Vector3D;
    north_source: "true_north" | "scan_forward";
  };
  dimensions: {
    width_m: number;
    length_m: number;
    ceiling_height_m: number;
  };
  surfaces: RoomPlanSurfaceSeed[];
  openings: RoomPlanOpeningSeed[];
  objects: RoomPlanObjectSeed[];
  fixed_elements?: RoomPlanFixedElementSeed[] | null;
  room_count?: number | null;
}

export interface CaptureMetadata {
  room_type_hint: "bedroom";
  units: "m";
  device_model: string;
  captured_at: ISO8601Timestamp;
  video_expected: boolean;
}

export interface SupplementaryDetection {
  detection_id: string;
  label: string;
  obb: OBB3D;
  confidence: number;
}

export interface RoomPlanCaptureResponse {
  scene_id: SceneId;
  scene_version: number;
  scene_snapshot_id: SnapshotId;
  handoff_url: string;
  qr_payload: string;
  expires_at: ISO8601Timestamp;
  video_upload_token: string | null;
}

export interface HandoffRedeemRequest {
  handoff_token: string;
}

export interface HandoffRedeemResponse {
  scene_id: SceneId;
  session_id: string;
  redeemed_at: ISO8601Timestamp;
  expires_at: ISO8601Timestamp;
}

export interface OperationPlanRequest {
  request_id: string;
  idempotency_key: string;
  scene_id: SceneId;
  expected_scene_version: number;
  selection_context: {
    selected_entity_ids: EntityId[];
  };
  user_prompt: string;
}

export interface OperationPlanPreview {
  request_id: string;
  preview_id: string;
  based_on_scene_version: number;
  ops: SceneEditOperation[];
  explanation: string;
  canonical_plan_hash: string;
  apply_token: string;
  apply_token_expires_at: ISO8601Timestamp;
  idempotency_key: string;
}

export interface CommandRequest {
  request_id: string;
  command_kind: CommandKind;
  endpoint: string;
  explanation: string;
  idempotency_key: string;
}

export interface ApplyPlanRequest {
  preview_id: string;
  apply_token: string;
  canonical_plan_hash: string;
  expected_scene_version: number;
  idempotency_key: string;
}

export interface ClarificationRequest {
  response_kind: "clarification_request";
  request_id: string;
  prompt: string;
  options: string[];
}

export interface OperationPlanPreviewResponse {
  response_kind: "operation_plan_preview";
  preview: OperationPlanPreview;
}

export interface CommandRequestResponse {
  response_kind: "command_request";
  command: CommandRequest;
}

export interface RejectionResponse {
  response_kind: "rejection";
  request_id: string;
  reason_code: ReasonCode;
  message: string;
}

export type PlannerResponse =
  | ClarificationRequest
  | OperationPlanPreviewResponse
  | CommandRequestResponse
  | RejectionResponse;

export interface MoveObjectOperation {
  op: "move_object";
  object_id: EntityId;
  target_position: Point3D;
  target_named_wall_ref_id?: EntityId | null;
  target_window_opening_id?: EntityId | null;
  include_children?: boolean;
}

export interface RotateObjectOperation {
  op: "rotate_object";
  object_id: EntityId;
  yaw_degrees: number;
  include_children?: boolean;
}

export interface ReplaceObjectOperation {
  op: "replace_object";
  object_id: EntityId;
  desired_class: EditableObjectClass;
  style_tags: string[];
  asset_id?: AssetId | null;
}

export interface PlacementRelation {
  relation: "named_wall" | "window" | "surface_point";
  target_entity_id: EntityId;
  offset_meters?: number;
}

export interface AddObjectOperation {
  op: "add_object";
  object_id: EntityId;
  object_class: EditableObjectClass;
  style_tags: string[];
  placement_relation?: PlacementRelation | null;
  pose?: Pose3D | null;
}

export interface RemoveObjectOperation {
  op: "remove_object";
  object_id: EntityId;
}

export interface LockEntityOperation {
  op: "lock_entity";
  entity_id: EntityId;
  entity_type: "object" | "surface";
}

export interface UnlockEntityOperation {
  op: "unlock_entity";
  entity_id: EntityId;
  entity_type: "object" | "surface";
}

export interface RepaintSurfaceOperation {
  op: "repaint_surface";
  surface_id: EntityId;
  color: string;
  finish?: string | null;
}

export interface SwapFlooringOperation {
  op: "swap_flooring";
  surface_id: EntityId;
  material_state: MaterialState;
}

export type SceneEditOperation =
  | MoveObjectOperation
  | RotateObjectOperation
  | ReplaceObjectOperation
  | AddObjectOperation
  | RemoveObjectOperation
  | LockEntityOperation
  | UnlockEntityOperation
  | RepaintSurfaceOperation
  | SwapFlooringOperation;

export interface SceneReadResponse {
  scene: Scene;
}

export interface SceneApplyResponse {
  scene: Scene;
  applied_snapshot_id: SnapshotId;
  applied_scene_version: number;
  validation_summary: {
    hard_violations: Array<Record<string, unknown>>;
    soft_scores: Record<string, number>;
  };
}

export interface GeneratePhotorealRequest {
  scene_snapshot_id: SnapshotId;
  bookmark_id?: string | null;
  camera_pose?: Pose3D | null;
  fov?: number | null;
  prompt_modifiers: string[];
  idempotency_key: string;
}

export interface UndoLastChangeRequest {
  expected_scene_version: number;
  idempotency_key: string;
}

export interface VideoUploadRequest {
  video_upload_token: string;
  content_type: string;
}

export interface VideoUploadResponse {
  job_id: JobId;
}

export interface DeleteSceneRequest {
  idempotency_key: string;
}

export interface JobRecord {
  job_id: JobId;
  scene_id: SceneId;
  job_kind: JobKind;
  status: JobStatus;
  source_scene_version: number | null;
  scene_snapshot_id: SnapshotId | null;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
  output_asset_id: AssetId | null;
  error_code: ReasonCode | null;
}

export interface HandoffGrantRecord {
  grant_id: string;
  scene_id: SceneId;
  token_hash: string;
  qr_payload: string;
  status: HandoffGrantStatus;
  expires_at: ISO8601Timestamp;
  redeemed_at: ISO8601Timestamp | null;
  redeemed_session_id?: string | null;
}

export interface VideoUploadTokenRecord {
  token_id: string;
  scene_id: SceneId;
  token_hash: string;
  status: VideoUploadTokenStatus;
  expires_at: ISO8601Timestamp;
  used_at: ISO8601Timestamp | null;
  created_at: ISO8601Timestamp;
}

export interface IdempotencyRecord {
  scope: string;
  idempotency_key: string;
  request_hash: string;
  response_status_code: number;
  response_body: Record<string, unknown>;
  scene_id: SceneId | null;
  created_at: ISO8601Timestamp;
  updated_at: ISO8601Timestamp;
}

export interface RoomPlanSurfaceSeed {
  id: string;
  category: "wall" | "floor" | "ceiling";
  polygon: Polygon2D;
  frame: {
    origin: Point3D;
    u_axis: Vector3D;
    v_axis: Vector3D;
    normal: Vector3D;
  } | null;
